package bottlesong

import (
	"fmt"
	"strings"
)

// numberWords maps bottle counts to their capitalized word forms.
var numberWords = map[int]string{
	0: "No", 1: "One", 2: "Two", 3: "Three", 4: "Four",
	5: "Five", 6: "Six", 7: "Seven", 8: "Eight", 9: "Nine", 10: "Ten",
}

// lowerFirst returns s with its first character lowercased.
func lowerFirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToLower(s[:1]) + s[1:]
}

// bottleName returns "green bottle" for one bottle and "green bottles"
// for any other count.
func bottleName(count int) string {
	if count == 1 {
		return "green bottle"
	}
	return "green bottles"
}

// verse returns the four lines of a single verse for the given count.
func verse(count int) []string {
	number := numberWords[count]
	return []string{
		fmt.Sprintf("%s %s hanging on the wall,", number, bottleName(count)),
		fmt.Sprintf("%s %s hanging on the wall,", number, bottleName(count)),
		"And if one green bottle should accidentally fall,",
		fmt.Sprintf("There'll be %s %s hanging on the wall.", lowerFirst(numberWords[count-1]), bottleName(count-1)),
	}
}

// Recite returns the verses of the song, starting from startBottles and
// taking down takeDown bottles, with verses separated by blank lines.
func Recite(startBottles, takeDown int) []string {
	var lines []string
	for i := 0; i < takeDown; i++ {
		if i > 0 {
			lines = append(lines, "")
		}
		lines = append(lines, verse(startBottles-i)...)
	}
	return lines
}
